import csv
import io
import re


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    try:
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    except csv.Error:
        records = list(csv.reader(io.StringIO(raw_csv), delimiter=",", quotechar='"', strict=False))

    records = [[str(value) for value in row] for row in records]
    expected_width = 9
    header_count = 3

    def is_blank(row):
        return not row or all(value.strip() == "" for value in row)

    def resembles_data(row):
        if not row:
            return False
        first = row[0].strip()
        if re.match(r"^\d{1,4}[-/.]\d{1,2}[-/.]\d{1,4}$", first):
            return True
        if len(row) >= 3:
            second = row[1].strip()
            third = row[2].strip()
            if re.match(r"^\d{1,2}:\d{2}(?::\d{2})?(?:\s*[APap][Mm])?$", second):
                return True
            if re.match(r"^[+-]?\d+(?:\.\d+)?$", third):
                return True
        return len(row) == expected_width

    def header_text_score(rows):
        score = 0
        for row in rows:
            for value in row:
                value = value.strip()
                if value:
                    score += 1
                    if re.search(r"[A-Za-z]", value):
                        score += 1
                    if resembles_data([value]):
                        score -= 2
        return score

    candidates = []
    for index in range(max(0, len(records) - header_count + 1)):
        block = records[index:index + header_count]
        if len(block) != header_count or any(is_blank(row) for row in block):
            continue

        concatenated = sum(len(row) for row in block) == expected_width
        stacked = all(len(row) == expected_width for row in block)
        if not concatenated and not stacked:
            continue

        next_index = index + header_count
        while next_index < len(records) and is_blank(records[next_index]):
            next_index += 1

        score = header_text_score(block)
        if concatenated:
            score += 10
        if next_index < len(records):
            next_row = records[next_index]
            if len(next_row) == expected_width:
                score += 20
            if resembles_data(next_row):
                score += 20
        candidates.append((score, -index, index, concatenated))

    if candidates:
        _, _, header_start, concatenate_headers = max(candidates)
    else:
        nonblank_indices = [i for i, row in enumerate(records) if not is_blank(row)]
        header_start = nonblank_indices[0] if nonblank_indices else 0
        concatenate_headers = True

    header_rows = records[header_start:header_start + header_count]

    if concatenate_headers:
        columns = []
        for row in header_rows:
            columns.extend(row)
    else:
        columns = []
        for column_index in range(expected_width):
            parts = []
            for row in header_rows:
                if column_index < len(row):
                    part = row[column_index].strip()
                    if part and part not in parts:
                        parts.append(part)
            columns.append(" ".join(parts))

    if len(columns) < expected_width:
        columns.extend("" for _ in range(expected_width - len(columns)))
    elif len(columns) > expected_width:
        columns = columns[:expected_width - 1] + [",".join(columns[expected_width - 1:])]

    for index, value in enumerate(columns):
        if value == "":
            columns[index] = "Column" + str(index + 1)

    def normalize_row(row):
        row = list(row)
        if len(row) == expected_width:
            return row
        if len(row) < expected_width:
            return row + [""] * (expected_width - len(row))

        url_index = None
        for index in range(5, len(row)):
            if re.match(r"^(?:https?://|www\.)", row[index].strip(), re.IGNORECASE):
                url_index = index
                break

        if url_index is not None and url_index >= 7:
            normalized = row[:5]
            normalized.append(row[5])
            normalized.append(",".join(row[6:url_index]))
            normalized.append(row[url_index])
            normalized.append(",".join(row[url_index + 1:]))
            return normalized

        return row[:expected_width - 1] + [",".join(row[expected_width - 1:])]

    rows = []
    data_start = header_start + header_count
    data_seen = False

    for row in records[data_start:]:
        if is_blank(row):
            continue

        if len(row) == 1 and not resembles_data(row):
            if data_seen:
                continue
            continue

        if len(row) == 2 and data_seen and not resembles_data(row):
            continue

        if len(row) >= 3 or resembles_data(row):
            rows.append(normalize_row(row))
            data_seen = True

    return {"columns": columns, "rows": rows}
